  border:none !important;
  -webkit-backdrop-filter:none !important;
          backdrop-filter:none !important;

  /* 四个角：左上 右上 右下 左下 */
  border-radius:var(--nj-r-tl) var(--nj-r-tr) var(--nj-r-br) var(--nj-r-bl) !important;

  /* 高度：垂直居中，不挤别的按钮 */
